import{z as s,x as p,o as r,c as B,q as i,j as n,D as E,d as t,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"地理复制","description":"","frontmatter":{"title":"地理复制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/geo-replication.md","filePath":"cs/geo-replication.md","lastUpdated":1791063341000}'),d={name:"cs/geo-replication.md"};function C(m,a,D,T,S,P){const l=p("Mermaid");return r(),B("div",null,[a[2]||(a[2]=i('<h1 id="地理复制" tabindex="-1">地理复制 <a class="header-anchor" href="#地理复制" aria-label="Permalink to &quot;地理复制&quot;">​</a></h1><div class="epigraph"><p>跨数据中心的延迟下限是光速。同步复制买线性一致，付跨洋 RTT；异步复制买本地写，付冲突与数据丢失窗口。</p><footer>—— 据 Corbett et al., Spanner, OSDI 2012；Lloyd et al., COPS, SOSP 2011；PACELC 整理</footer></div><p>上一课<a href="/cs/distributed-id">分布式 ID</a>的时间序在跨区更不可靠。缺口是<strong>多机房同一逻辑数据</strong>：CAP 的分区变成经常性的延迟与真切断。本课钉同步/异步地理复制与因果+，不重写 TrueTime 全部。后课滚动升级是机房内变更，可与跨区流量编排叠在一起。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同步：写等跨区多数派，线性一致可能，延迟 ≥ RTT。异步：本地提交，对端追，RPO &gt; 0，冲突用 LWW/CRDT/会话。COPS：在最终一致上加强因果+（读到的值的依赖都在）。Spanner：用 TrueTime 的 \\(\\varepsilon\\) 做 commit wait，给外部一致事务——依赖时钟 API，不是普通 NTP。</p><p>缺口：把「多 AZ」当地理。同城同步与跨洋异步档位不同。DNS 切流量不是 fencing。</p><p><span class="marginnote">Spanner 论文是外部一致与 TrueTime。COPS 是因果+。二者都不要缩写成「有了地理复制就强一致」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读本地、写本地：AP/L。写本地、读全局：看是否等复制。写全局主：一区当主，他区只读，failover 接<a href="/cs/primary-backup-failover">主备</a>与脑裂。多主：必须冲突规则。</p>',9)),(r(),n(A,null,{default:E(()=>[o(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%22%5D%20--%3E%20SYNC%7B%22%E7%AD%89%E8%B7%A8%E5%8C%BA%3F%22%7D%0A%20%20SYNC%20--%3E%7C%22%E6%98%AF%22%7C%20LIN%5B%22%E5%8F%AF%E7%BA%BF%E6%80%A7%20%2F%20%E5%A4%96%E9%83%A8%E4%B8%80%E8%87%B4%22%5D%0A%20%20SYNC%20--%3E%7C%22%E5%90%A6%22%7C%20ASY%5B%22%E6%9C%AC%E5%9C%B0%E6%88%90%E5%8A%9F%20%2B%20%E8%BF%BD%E8%B5%B6%22%5D%0A%20%20ASY%20--%3E%20CF%5B%22%E5%86%B2%E7%AA%81%20%2F%20%E5%9B%A0%E6%9E%9C%2B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"对象存储跨区复制通常异步，接 S3 课。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"分区：跨区链路比机房内更容易长时间分区。CP 系统少数派机房必须拒写。PACELC 的 EL 在无分区时仍付 RTT。时钟：跨区 \\(\\varepsilon\\) 更大，HLC 更常靠计数；TrueTime 用 GPS/原子钟把 \\(\\varepsilon\\) 暴露。",-1)),a[6]||(a[6]=e("p",null,"本课不写具体云厂商的 Active-Active 广告。也不写 LOB 跨区撮合。",-1)),a[7]||(a[7]=e("p",null,"会话：用户跟着 DNS 跳机房会破 RYW，除非把会话向量带走或粘滞。接会话保证课。",-1)),a[8]||(a[8]=e("p",null,[e("span",{class:"marginnote"},"数字实例：北京到弗吉尼亚直线约 1.1 万公里，光在光纤里速度约为真空的 2/3，单程就要 55 ms，往返 RTT 起步 110 ms。若每次写都等跨区多数派确认，一秒最多做不了几次写；同城 RTT 只有 1-2 ms，同样的同步复制几乎无感——这就是「同城同步、跨洋异步」档位的由来。")],-1)),a[9]||(a[9]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：RPO（恢复点目标）回答「灾难发生时最多丢多久的数据」：异步复制 RPO 可能是几秒，等于这几秒的写入永久丢失；RTO（恢复时间目标）回答「多久恢复服务」。DNS 切流量只改善 RTO，对 RPO 毫无帮助。")],-1)),(r(),n(A,null,{default:E(()=>[o(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E6%9C%BA%E6%88%BF%E7%81%BE%E9%9A%BE%E5%8F%91%E7%94%9F%22%5D%20--%3E%20Q%7B%22%E5%A4%8D%E5%88%B6%E6%A1%A3%E4%BD%8D%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%8C%E6%AD%A5%E8%B7%A8%E5%8C%BA%22%7C%20OK%5B%22%E5%A4%9A%E6%95%B0%E6%B4%BE%E5%B7%B2%E6%9C%89%E6%95%B0%E6%8D%AE%20RPO%20%E4%B8%BA%200%22%5D%0A%20%20Q%20--%3E%7C%22%E5%BC%82%E6%AD%A5%E8%B7%A8%E5%8C%BA%22%7C%20GAP%5B%22%E5%AF%B9%E7%AB%AF%E8%90%BD%E5%90%8E%E6%95%B0%E7%A7%92%20RPO%20%E5%A4%A7%E4%BA%8E%200%22%5D%0A%20%20GAP%20--%3E%20REC%5B%22%E5%88%87%E6%8D%A2%20DNS%20%E6%B5%81%E9%87%8F%22%5D%0A%20%20REC%20--%3E%20LOSE%5B%22%E7%AA%97%E5%8F%A3%E5%86%85%E5%86%99%E5%85%A5%E4%B8%A2%E5%A4%B1%E6%88%96%E5%86%B2%E7%AA%81%22%5D%0A%20%20OK%20--%3E%20REC2%5B%22%E5%88%87%E6%8D%A2%E5%8D%B3%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[10]||(a[10]=i('<p><span class="marginnote">常见误区：初学者容易以为「三个机房各存一份就不会丢数据」。若复制是异步的，主机房在把日志发出去之前断电，三份副本的承诺一个都没兑现——副本数解决的是机器坏，解决不了「写入还没离开本地」这个窗口。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Spanner 并发控制。后课默认：跨区先选 RPO/RTO 与一致档；不要默认多主 LWW。滚动升级下一课处理版本异构，地理复制期间双版本更常见。TLA+ 最后课给这些协议一个规格语言。</p><p>光速是墙。协议只能把墙换成冲突或延迟，不能拆墙。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同步跨区：延迟换强一致；异步：RPO 与冲突。</li><li>COPS 因果+、Spanner 外部一致是不同档。</li><li>跨区分区更长，少数派必须有拒写故事。</li><li>出处：Corbett et al., OSDI 2012；Lloyd et al., SOSP 2011。</li></ul>',6))])}const O=s(d,[["render",C]]);export{f as __pageData,O as default};
